import pyomo.environ as pyo

DATA = {
    "bets": ["basketball", "horse_race", "soccer"],
    "bankroll": 100000.0,
    "loss_prob": {"basketball": 0.50, "horse_race": 0.25, "soccer": 0.10},
    "payout": {"basketball": 1.2, "horse_race": 0.5, "soccer": 0.1},
    "risk_cap": 0.30,
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["bets"])

    def _ub(m, i):
        return (0.0, float(d["bankroll"]))

    model.stake = pyo.Var(model.I, domain=pyo.NonNegativeReals,
                          bounds=_ub)

    def obj_rule(m):
        return sum(d["payout"][i] * m.stake[i] for i in m.I)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def budget_rule(m):
        return sum(m.stake[i] for i in m.I) <= float(d["bankroll"])

    model.budget = pyo.Constraint(rule=budget_rule)

    def risk_rule(m):
        return sum((d["loss_prob"][i] - d["risk_cap"]) * m.stake[i]
                   for i in m.I) <= 0.0

    model.risk = pyo.Constraint(rule=risk_rule)

    return model


