import pyomo.environ as pyo

DATA = {
    "bets": ["basketball", "horse", "soccer"],
    "bankroll": 100000,
    "loss_prob": {"basketball": 0.50, "horse": 0.25, "soccer": 0.10},
    "payout": {"basketball": 1.2, "horse": 0.5, "soccer": 0.1},
    "max_avg_loss": 0.30,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.BETS = pyo.Set(initialize=d["bets"])

    model.amount = pyo.Var(
        model.BETS,
        domain=pyo.NonNegativeReals,
        bounds=(0, d["bankroll"]),
    )

    def obj_rule(m):
        return sum(d["payout"][b] * m.amount[b] for b in m.BETS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def bankroll_rule(m):
        return sum(m.amount[b] for b in m.BETS) <= d["bankroll"]

    model.bankroll_limit = pyo.Constraint(rule=bankroll_rule)

    def avg_loss_rule(m):
        return (
            sum(d["loss_prob"][b] * m.amount[b] for b in m.BETS)
            <= d["max_avg_loss"] * sum(m.amount[b] for b in m.BETS)
        )

    model.avg_loss_limit = pyo.Constraint(rule=avg_loss_rule)

    return model


