import pyomo.environ as pyo

DATA = {
    "bets": ["basketball", "horse", "soccer"],
    "budget": 100000.0,
    "loss_prob": {
        "basketball": 0.50,
        "horse": 0.25,
        "soccer": 0.10,
    },
    "payout_per_dollar": {
        "basketball": 1.2,
        "horse": 0.5,
        "soccer": 0.1,
    },
    "max_avg_loss_prob": 0.30,
    "big_M": 100000.0,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.I = pyo.Set(initialize=d["bets"])

    # Variables: money placed on each bet
    model.x = pyo.Var(
        model.I,
        within=pyo.NonNegativeReals,
        bounds=(0.0, d["budget"]),
    )

    # Objective: maximize total expected payout
    def obj_rule(m):
        return sum(d["payout_per_dollar"][i] * m.x[i] for i in m.I)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Constraint 1: total money bet cannot exceed the bankroll (100000)
    def budget_rule(m):
        return sum(m.x[i] for i in m.I) <= d["budget"]

    model.budget_limit = pyo.Constraint(rule=budget_rule)

    # Constraint 2: average (investment-weighted) loss probability <= 30%
    #   sum_i loss_i * x_i  <= 0.30 * sum_i x_i
    # => sum_i (loss_i - 0.30) * x_i <= 0
    def avg_loss_rule(m):
        return sum(
            (d["loss_prob"][i] - d["max_avg_loss_prob"]) * m.x[i] for i in m.I
        ) <= 0.0

    model.avg_loss_limit = pyo.Constraint(rule=avg_loss_rule)

    return model


